const body = pm.response.json();

if (!Array.isArray(body)) {
    console.log("Expected an array but received:", body);
    throw new Error("Response is not an array");
}

const wantedNodes = {
    "Kenya Enterprise Limited": "generic_company_node_id",
    "Board & Governance": "board_governance_node_id",
    "Office of the Managing Director": "md_office_node_id",
    "Finance & Strategy Division": "finance_strategy_node_id",
    "Operations Division": "operations_division_id",
    "Human Resources & Administration Division": "hr_admin_division_id",
    "Technology Division": "technology_division_id",
    "Risk & Compliance Division": "risk_compliance_division_id",
    "Legal & Corporate Affairs Division": "legal_corporate_division_id",
    "Sales & Customer Experience Division": "sales_customer_division_id",
    "Finance Department": "finance_department_id",
    "Operations Department": "operations_department_id",
    "Procurement & Supply Chain Department": "procurement_department_id",
    "Quality & Process Improvement Department": "quality_department_id"
};

let storedCount = 0;

body.forEach((node) => {
    const variableName = wantedNodes[node.name];

    if (variableName) {
        pm.collectionVariables.set(variableName, node.id);

        console.log(
            `Stored ${variableName} = ${node.id}`
        );

        storedCount++;
    }
});

console.log(`Stored ${storedCount} node variables.`);

